// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Interface describing `dlaqsy`.
*/
interface Routine {
	/**
	* Equilibrates a real symmetric matrix `A` using the scaling factors in the vector `S`.
	*
	* @param order - storage layout
	* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is referenced
	* @param N - order of the matrix `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param S - vector of scale factors
	* @param scond - ratio of the smallest scale factor to the largest scale factor
	* @param amax - absolute value of the largest matrix entry
	* @returns character flag indicating whether the matrix was equilibrated (`'Y'`) or not (`'N'`)
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
	* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
	*
	* dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625, 9.0 );
	* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
	*/
	( order: Layout, uplo: MatrixTriangle, N: number, A: Float64Array, LDA: number, S: Float64Array, scond: number, amax: number ): string;

	/**
	* Equilibrates a real symmetric matrix `A` using the scaling factors in the vector `S` and alternative indexing semantics.
	*
	* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is referenced
	* @param N - order of the matrix `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param S - vector of scale factors
	* @param strideS - stride length for `S`
	* @param offsetS - starting index for `S`
	* @param scond - ratio of the smallest scale factor to the largest scale factor
	* @param amax - absolute value of the largest matrix entry
	* @returns character flag indicating whether the matrix was equilibrated (`'Y'`) or not (`'N'`)
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
	* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
	*
	* dlaqsy.ndarray( 'upper', 3, A, 3, 1, 0, S, 1, 0, 0.0625, 9.0 );
	* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
	*/
	ndarray( uplo: MatrixTriangle, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, S: Float64Array, strideS: number, offsetS: number, scond: number, amax: number ): string;
}

/**
* Equilibrates a real symmetric matrix `A` using the scaling factors in the vector `S`.
*
* @param order - storage layout
* @param uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` is referenced
* @param N - order of the matrix `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param S - vector of scale factors
* @param scond - ratio of the smallest scale factor to the largest scale factor
* @param amax - absolute value of the largest matrix entry
* @returns character flag indicating whether the matrix was equilibrated (`'Y'`) or not (`'N'`)
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
*
* dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625, 9.0 );
* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
*
* dlaqsy.ndarray( 'upper', 3, A, 3, 1, 0, S, 1, 0, 0.0625, 9.0 );
* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
*/
declare var dlaqsy: Routine;


// EXPORTS //

export = dlaqsy;
